"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["99642"],{32950(e){e.exports=JSON.parse('{"id":"FIN-1413","slug":"immediate-annuity","term":"Immediate Annuity","also_known_as":[],"difficulty":"Advanced","definition":"An immediate annuity is an insurance contract in which a person pays a lump sum to an insurer in exchange for regular income payments that begin straight away, often for the rest of their life.","explanation":["Immediate annuities are commonly bought by people at or near retirement to turn part of their savings into a guaranteed income. Payments typically begin within a month to a year of purchase.","For example, a 65-year-old might use 200,000 to buy an immediate lifetime annuity paying a fixed monthly income for as long as they live. The exact amount depends on their age, health, interest rates at the time and the features chosen.","Options can include payments that continue to a spouse after death, a guaranteed minimum payment period, and payments that increase each year to help offset inflation, which reduces the starting income.","The main advantage is protection against outliving savings, known as longevity risk. Disadvantages include giving up access to the lump sum, the possibility of dying early and receiving less than was paid, and, for fixed payments, loss of purchasing power over time. Annuity rates are higher when interest rates are high and for older buyers. In the United Kingdom and some other countries, people in poor health may qualify for enhanced annuities with higher payments."],"note":"","total":1500,"prev":{"slug":"if-converted-method","term":"If-Converted Method"},"next":{"slug":"impact-investing","term":"Impact Investing"}}')}}]);